            if file in CONFIG_SCAN_SKIP_FILES:
                continue
            if '.test.' in file.lower() or '.spec.' in file.lower() or file.lower().startswith('test_'):
                continue

            filepath = Path(root) / file
            file_abs = os.path.abspath(str(filepath))
            if file_abs in SKIP_FILES_PATTERN:
                continue  # Skip scanner's own source to avoid self-flagging

            try:
                with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()
                    if "security-scan:file-ignore" in content or "security-scan:ignore-file" in content:
                        continue

                    results["scanned_files"] += 1

                    for pattern, secret_type, severity in SECRET_PATTERNS:
                        matches = re.findall(pattern, content, re.IGNORECASE)
                        if matches:
                            results["findings"].append({
