            if ext not in CONFIG_EXTENSIONS and file not in ['next.config.js', 'webpack.config.js', '.eslintrc.js']:
                continue
            # Skip captured snapshot files — they contain patterns from scanned source, not live config.
            if file in CONFIG_SCAN_SKIP_FILES:
