                .commit_from_file(model_path)
                .map_err(|e| AppError::InfrastructureError {
                    provider_id: ProviderId::Audio,
                    kind: InfrastructureErrorKind::ApiError,
                    detail: format!("Failed to load model {}: {}", model_path, e),
                    help_link: None,
                })?,
            Err(e) => {
