#[derive(Debug, Clone, Serialize, Deserialize, sqlx::FromRow)]
pub struct BenchmarkResult {
    pub id: String,
    pub name: String,
    pub category: String,
    pub test_id: String,
    pub mean_ms: f64,
    pub p95_ms: Option<f64>,
    pub p99_ms: Option<f64>,
    pub target_value: Option<String>,
    pub status: String, // PASS | FAIL | NEEDS_INVESTIGATION
    pub metadata: Option<String>,
    pub created_at: String,
}

pub async fn save_benchmark(pool: &SqlitePool, result: BenchmarkResult) -> Result<(), AppError> {
    sqlx::query(
        "INSERT INTO benchmarks (id, name, category, test_id, mean_ms, p95_ms, p99_ms, target_value, status, metadata)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
    )
    .bind(&result.id)
    .bind(&result.name)
    .bind(&result.category)
    .bind(&result.test_id)
    .bind(result.mean_ms)
    .bind(result.p95_ms)
    .bind(result.p99_ms)
    .bind(&result.target_value)
    .bind(&result.status)
    .bind(&result.metadata)
    .execute(pool)
    .await?;

    Ok(())
}

pub async fn list_benchmarks(pool: &SqlitePool) -> Result<Vec<BenchmarkResult>, AppError> {
    let (results, _) = list_benchmarks_paginated(pool, 100, 0).await?;
    Ok(results)
}

pub async fn list_benchmarks_paginated(
    pool: &SqlitePool,
    limit: u32,
    offset: u32,
) -> Result<(Vec<BenchmarkResult>, u64), AppError> {
    let total: (i64,) = sqlx::query_as("SELECT COUNT(*) FROM benchmarks")
        .fetch_one(pool)
        .await?;

    let results = sqlx::query_as::<_, BenchmarkResult>(
        "SELECT id, name, category, test_id, mean_ms, p95_ms, p99_ms, target_value, status, metadata, CAST(created_at AS TEXT) as created_at \
         FROM benchmarks ORDER BY created_at DESC LIMIT ? OFFSET ?"
    )
    .bind(limit as i64)
    .bind(offset as i64)
    .fetch_all(pool)
    .await?;

    Ok((results, total.0 as u64))
}

pub async fn get_benchmark_comparison(
    pool: &SqlitePool,
    test_id: &str,
) -> Result<Vec<BenchmarkResult>, AppError> {
    let results = sqlx::query_as::<_, BenchmarkResult>(
        "SELECT id, name, category, test_id, mean_ms, p95_ms, p99_ms, target_value, status, metadata, CAST(created_at AS TEXT) as created_at FROM benchmarks WHERE test_id = ? ORDER BY created_at DESC LIMIT 10"
    )
