        }
        "BM-RL-01" => {
            name = "Rate Limiter Overhead".to_string();
            category = "Rate Limiter".to_string();
            target_value = Some("< 1ms".to_string());

            let limiter = crate::agent::rate_limiter::RateLimiter::new(Some(1000), Some(100000));
