pub struct GeminiProvider {
    client: Client,
    config: ModelConfig,
    api_key: String,
    /// In-memory cache map: SHA256(system_prompt) -> cache_resource_name
    cache_refs: dashmap::DashMap<String, String>,
}

impl GeminiProvider {
    pub fn new(client: Client, api_key: String, config: ModelConfig) -> Self {
        Self {
            client,
            config,
            api_key,
            cache_refs: dashmap::DashMap::new(),
        }
    }

    /// Computes the SHA256 hash for a given system prompt.
    fn compute_cache_hash(system_prompt: &str) -> String {
        use sha2::{Digest, Sha256};
        let mut hasher = Sha256::new();
        hasher.update(system_prompt.as_bytes());
        hex::encode(hasher.finalize())
    }

    async fn resolve_context_cache(&self, system_prompt: &str) -> Option<String> {
        if system_prompt.len() < 32768 {
            return None;
        }

        let hash = Self::compute_cache_hash(system_prompt);

        if let Some(r) = self.cache_refs.get(&hash) {
            return Some(r.clone());
        }

        let base_url = self
            .config
            .base_url
            .clone()
            .unwrap_or_else(|| "https://generativelanguage.googleapis.com/v1beta".to_string());
        let url = format!("{}/cachedContents", base_url);

        let body = CachedContentRequest {
            model: format!("models/{}", self.config.model_id),
            contents: vec![GeminiContent {
                role: "system".to_string(),
                parts: vec![GeminiPart {
                    text: system_prompt.to_string(),
                }],
            }],
            ttl: "3600s".to_string(),
        };

        match self
            .client
            .post(&url)
            .header("x-goog-api-key", &self.api_key)
            .json(&body)
            .send()
            .await
        {
            Ok(res) if res.status().is_success() => {
                if let Ok(parsed) = res.json::<CachedContentResponse>().await {
                    let name = parsed.name;
                    self.cache_refs.insert(hash, name.clone());
                    Some(name)
                } else {
                    None
                }
            }
            _ => None,
        }
    }

    pub async fn generate(
        &self,
        system_prompt: &str,
        user_message: &str,
        tools: Option<Vec<ToolDefinition>>,
    ) -> Result<(String, Vec<ToolCall>, Option<TokenUsage>), AppError> {
        let base_url = self
            .config
            .base_url
            .clone()
            .unwrap_or_else(|| "https://generativelanguage.googleapis.com/v1beta".to_string());
        let url = format!(
            "{}/models/{}:generateContent",
            base_url, self.config.model_id
        );

        let combined_prompt = format!("{}\n\nUSER MESSAGE:\n{}", system_prompt, user_message);

        let mut request_body = GeminiRequest {
            contents: vec![GeminiContent {
                role: "user".to_string(),
                parts: vec![GeminiPart {
                    text: combined_prompt.clone(),
                }],
            }],
            tools,
            user: self.config.external_id.clone(),
            cached_content: None,
            generation_config: None,
        };

        if let Some(sys) = &self.config.system_prompt {
            request_body.cached_content = self.resolve_context_cache(sys).await;
        } else if combined_prompt.contains("(cache_control: {\"type\": \"ephemeral\"})") {
            request_body.cached_content = self.resolve_context_cache(&combined_prompt).await;
        }

        let mut attempts = 0;
        let max_attempts = 5;

        loop {
            let res = self
                .client
                .post(&url)
                .header("x-goog-api-key", &self.api_key)
                .json(&request_body)
                .send()
                .await?;

            let status = res.status();

            if status.is_success() {
                let raw_text = res
                    .text()
                    .await
                    .map_err(|e| AppError::InfrastructureError {
                        provider_id: ProviderId::Gemini,
                        kind: InfrastructureErrorKind::NetworkError,
                        detail: format!("Failed to read Gemini response body stream: {}", e),
                        help_link: None,
                    })?;

                let parsed: GeminiResponse = match serde_json::from_str(&raw_text) {
                    Ok(p) => p,
                    Err(err) => {
                        tracing::error!(
                            "🚨 [Gemini] Failed to decode response JSON ({}). Raw response: {}",
                            err,
                            crate::error::safe_truncate_bytes(&raw_text, 1024)
                        );

                        if let Ok(err_val) = serde_json::from_str::<serde_json::Value>(&raw_text) {
                            if let Some(err_obj) = err_val.get("error") {
                                let msg = err_obj
                                    .get("message")
                                    .and_then(|m| m.as_str())
                                    .or_else(|| err_obj.as_str())
                                    .unwrap_or("Unknown upstream API error in 200 OK body");
                                return Err(AppError::InfrastructureError {
                                    provider_id: ProviderId::Gemini,
                                    kind: InfrastructureErrorKind::ApiError,
                                    detail: format!("Upstream API error: {}", msg),
                                    help_link: None,
                                });
                            }
                        }

                        return Err(AppError::InfrastructureError {
                            provider_id: ProviderId::Gemini,
                            kind: InfrastructureErrorKind::ApiError,
                            detail: format!(
                                "Error decoding Gemini response body ({}): {}",
                                err,
                                crate::error::safe_truncate_bytes(&raw_text, 500)
                            ),
                            help_link: None,
                        });
                    }
                };

                let mut output_text = String::new();
                let mut function_calls = Vec::new();

                if let Some(candidates) = parsed.candidates {
                    if let Some(candidate) = candidates.first() {
                        if let Some(content) = &candidate.content {
                            for part in &content.parts {
                                if let Some(text) = &part.text {
                                    output_text.push_str(text);
                                }
                                if let Some(fc) = &part.function_call {
                                    function_calls.push(ToolCall {
                                        name: fc.name.clone(),
                                        args: fc.args.clone(),
                                    });
                                }
                            }
                        }
                    }
                }

                let token_usage = parsed.usage_metadata.map(|usage| {
                    let input = usage.prompt_token_count.unwrap_or(0);
                    let output = usage.candidates_token_count.unwrap_or(0);
                    let total = usage.total_token_count.unwrap_or(input + output);
                    TokenUsage {
                        input_tokens: input,
                        output_tokens: output,
                        total_tokens: total,
                    }
                });

                return Ok((output_text, function_calls, token_usage));
            }

            if status == reqwest::StatusCode::TOO_MANY_REQUESTS {
                attempts += 1;
                if attempts >= max_attempts {
                    return Err(AppError::RateLimit(format!(
                        "Gemini Rate Limit Exceeded after {} attempts.",
                        max_attempts
                    )));
                }

                let retry_after = res
                    .headers()
                    .get("retry-after")
                    .and_then(|h| h.to_str().ok())
                    .and_then(|s| s.parse::<u64>().ok())
                    .unwrap_or_else(|| 2u64.pow(attempts));

                tracing::warn!(
                    "⏳ [Gemini] Rate Limit Hit (429). Attempt {}/{}. Retrying in {}s...",
                    attempts,
                    max_attempts,
                    retry_after
                );

                tokio::time::sleep(tokio::time::Duration::from_secs(retry_after)).await;
                continue;
            }

            if status == reqwest::StatusCode::FORBIDDEN {
                let error_text = res.text().await?;
                if error_text.to_lowercase().contains("quota") {
                    return Err(AppError::InfrastructureError {
                        provider_id: ProviderId::Gemini,
                        kind: InfrastructureErrorKind::RateLimit,
                        detail: format!("Quota Exhausted: {}", error_text),
                        help_link: Some("https://console.cloud.google.com/billing".to_string()),
                    });
                } else {
                    return Err(AppError::Forbidden(error_text));
                }
            }

            let error_text = res.text().await?;
            return Err(AppError::InfrastructureError {
                provider_id: ProviderId::Gemini,
                kind: InfrastructureErrorKind::ApiError,
                detail: error_text,
                help_link: None,
            });
        }
    }
}

#[async_trait::async_trait]
impl crate::agent::provider_trait::LlmProvider for GeminiProvider {
    async fn generate(
        &self,
        system_prompt: &str,
