            .config
            .base_url
            .clone()
            .unwrap_or_else(|| "https://generativelanguage.googleapis.com/v1beta".to_string());

        let embed_model = "gemini-embedding-001";
        let url = format!("{}/models/{}:embedContent", base_url, embed_model);

