            embedding: EmbeddingValues,
        }
        #[derive(Debug, Deserialize)]
        struct EmbeddingValues {
            values: Vec<f32>,
        }

        let parsed: EmbedResponse = res
            .json()
            .await
            .map_err(|e| AppError::InternalServerError(e.to_string()))?;
        Ok(parsed.embedding.values)
    }
}

