    #[test]
    fn test_flat_model_slots_2_3_deserialization() {
        let json = r#"{
            "model2": "llama-3",
            "model3": "mixtral-8x7b"
        }"#;

        let update: AgentConfigUpdate =
            serde_json::from_str(json).expect("Flat slots 2/3 deserialization failed");
        assert_eq!(update.model_2, Some("llama-3".to_string()));
        assert_eq!(update.model_3, Some("mixtral-8x7b".to_string()));
    }

    #[test]
    fn test_agent_config_sampling_params_merge() {
        let mut agent = EngineAgent {
            models: crate::agent::types::AgentModels {
                model: crate::agent::types::ModelConfig {
                    provider: crate::agent::types::ModelProvider::Anthropic,
                    model_id: "claude-3".to_string(),
                    ..Default::default()
                },
                ..Default::default()
            },
            ..Default::default()
        };

        let update = AgentConfigUpdate {
            top_p: Some(0.9),
            top_k: Some(50),
            ..Default::default()
        };

        let changed = update.apply_to(&mut agent);
        assert!(changed);

        let extras = agent
            .models
            .model
            .extra_parameters
            .as_ref()
            .expect("Extras missing");
        assert_eq!(extras.get("top_p").unwrap(), &serde_json::json!(0.9f32));
        assert_eq!(extras.get("top_k").unwrap(), &serde_json::json!(50));

        assert_eq!(
            agent.models.model.provider,
            crate::agent::types::ModelProvider::Anthropic
        );
        assert_eq!(agent.models.model.model_id, "claude-3");
    }
