use crate::agent::types::EngineAgent;
use crate::error::AppError;
use crate::state::AppState;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::Arc;
use tracing::{error, info};

/// A declarative definition of a specialized agent within a swarm recipe.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AgentRecipe {
    pub id: String,
    pub name: String,
    pub role: String,
    pub department: String,
    pub description: String,
    pub model_id: String,
    #[serde(default)]
    pub skills: Vec<String>,
    #[serde(default)]
    pub workflows: Vec<String>,
}

/// A declarative swarm blueprint for auto-bootstrapping mission specialists.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SwarmRecipe {
    pub name: String,
    pub description: String,
    pub agents: Vec<AgentRecipe>,
}

/// Scans the .agent/recipes directory for YAML blueprints and ingests them into the registry.
pub async fn auto_ingest_recipes(state: Arc<AppState>) {
    let recipe_dir = state.base_dir.join(".agent").join("recipes");
    if !recipe_dir.exists() {
        let _ = tokio::fs::create_dir_all(&recipe_dir).await;
        // Seed default recipe if empty?
        return;
    }

    match tokio::fs::read_dir(&recipe_dir).await {
        Ok(mut entries) => {
            while let Ok(Some(entry)) = entries.next_entry().await {
                let path = entry.path();
                if path.is_file()
                    && (path.extension() == Some("yaml".as_ref())
                        || path.extension() == Some("yml".as_ref()))
                {
                    if let Err(e) = ingest_recipe(path, state.clone()).await {
                        error!("🚨 [Recipes] Failed to ingest recipe: {}", e);
                    }
                }
            }
        }
        Err(e) => error!("🚨 [Recipes] Failed to read recipe directory: {}", e),
    }
}

async fn ingest_recipe(path: PathBuf, state: Arc<AppState>) -> Result<(), AppError> {
    let content = tokio::fs::read_to_string(&path)
        .await
        .map_err(AppError::Io)?;
    let recipe: SwarmRecipe =
        serde_yaml::from_str(&content).map_err(|e| AppError::BadRequest(e.to_string()))?;

    info!(
        "🍳 [Recipes] Ingesting Swarm Recipe: {} ({} agents)",
        recipe.name,
        recipe.agents.len()
    );

    for a in recipe.agents {
        // Map AgentRecipe to EngineAgent
        let mut agent = EngineAgent {
            identity: crate::agent::types::AgentIdentity {
                id: a.id.clone(),
                name: a.name,
                role: a.role,
                department: a.department,
                description: a.description,
                category: "user".to_string(),
                ..Default::default()
            },
            models: crate::agent::types::AgentModels {
                model_id: Some(a.model_id.clone()),
                model: crate::agent::types::ModelConfig {
                    model_id: a.model_id,
                    ..Default::default()
                },
                ..Default::default()
            },
            capabilities: crate::agent::types::AgentCapabilities {
                skills: a.skills,
                workflows: a.workflows,
                ..Default::default()
            },
            health: crate::agent::types::AgentHealth {
                status: "idle".to_string(),
                ..Default::default()
            },
            metadata: HashMap::new(),
            ..Default::default()
        };

        // Fetch current version if agent already exists to avoid OCC (version mismatch) conflict
        if let Ok(Some(existing_version)) =
            sqlx::query_scalar::<_, i64>("SELECT version FROM agents WHERE id = ?1")
                .bind(&agent.identity.id)
                .fetch_optional(&state.resources.pool)
                .await
        {
            agent.version = existing_version as u32;
        }

        // UPSERT into database
        if let Err(e) =
            crate::agent::persistence::save_agent_db(&state.resources.pool, &mut agent).await
        {
            error!(
                "🚨 [Recipes] Failed to persist agent '{}': {}",
                agent.identity.id, e
            );
        } else {
            // Update in-memory registry
            state
                .registry
                .agents
                .insert(agent.identity.id.clone(), agent);
        }
    }

    Ok(())
}

