//! - **Local Errors**: none
//! - **Telemetry Targets**: `[IKS]`
//! - **Witness Tests**: none declared

use super::store::KnowledgeStore;
use super::types::{KnowledgeEntry, KnowledgeSearchRequest};
use crate::error::AppError;
#[cfg(feature = "vector-memory")]
use std::collections::HashMap;

const HUMAN_CONFIRMED_SCORE_MULTIPLIER: f32 = 2.0;
const SIMILARITY_RANK_WEIGHT: f32 = 0.5;

impl KnowledgeStore {
    /// Hybrid search: LanceDB k-NN with native metadata pre-filter → SQLite hydration → re-rank.
    ///
    /// LanceDB schema contains: `id`, `text`, `mission_id`, `timestamp`, `vector`.
    /// Relational metadata (`topic`, `confidence`, `ttl`, `cluster_id`, `concept_type`, `security_tier`)
    /// is strictly verified during SQLite hydration.
    pub async fn search(
        &self,
        req: &KnowledgeSearchRequest,
        http_client: reqwest::Client,
    ) -> Result<Vec<KnowledgeEntry>, AppError> {
        let limit = (req.limit.unwrap_or(10) as i64).clamp(1, 100);
        let min_confidence = (req.min_confidence.unwrap_or(0.3) as f64).clamp(0.0, 1.0);
        let trimmed_query = req.query.trim();

        // ── Empty Query Fast-Path ──────────────────────────────────────────
        // When query is empty, short-circuit directly to relational listing without embedding.
        if trimmed_query.is_empty() {
            return self
                .search_sqlite_fallback(req, limit, min_confidence)
                .await;
        }

        // ── Vector Path (LanceDB + SQLite Hydration) ───────────────────────
        #[cfg(feature = "vector-memory")]
        {
            let privacy_mode = std::env::var("PRIVACY_MODE")
                .map(|v| v.to_lowercase() == "true" || v == "1")
                .unwrap_or(false);

            if privacy_mode {
                tracing::info!("[IKS] PRIVACY_MODE active — falling back to SQLite text search");
                return self
                    .search_sqlite_fallback(req, limit, min_confidence)
                    .await;
            }

            let api_key = match std::env::var("GOOGLE_API_KEY") {
                Ok(key) if !key.is_empty() => key,
                _ => {
                    tracing::warn!(
                        "[IKS] GOOGLE_API_KEY missing — falling back to SQLite text search"
                    );
                    return self
                        .search_sqlite_fallback(req, limit, min_confidence)
                        .await;
                }
            };

            let query_vector =
                crate::agent::memory::get_gemini_embedding(&http_client, &api_key, trimmed_query)
                    .await?;

            // LanceDB schema has id, text, mission_id, timestamp, vector.
            let mut predicates: Vec<String> = Vec::new();
            if let Some(topic) = &req.topic {
                let escaped_topic = topic
                    .to_lowercase()
                    .replace('\\', "\\\\")
                    .replace('\'', "''");
                predicates.push(format!("mission_id = '{}'", escaped_topic));
            }
            let predicate = predicates.join(" AND ");

            let lance = self.get_lance().await?;
            lance.ensure_table().await?;

            // Over-fetch from ANN index so post-hydration relational filters don't starve results
            let fetch_limit = (limit as usize).saturating_mul(3).max(30);
            let hits = lance
                .search_knowledge_filtered(query_vector, fetch_limit, &predicate)
                .await?;

            if hits.is_empty() {
                return Ok(vec![]);
            }

            // Map hit index to compute semantic rank score
            let hit_count = hits.len() as f32;
            let mut semantic_ranks: HashMap<String, f32> = HashMap::new();
            let mut hit_text: HashMap<String, String> = HashMap::new();
            for (idx, h) in hits.into_iter().enumerate() {
                let rank_weight = 1.0 - (idx as f32 / hit_count);
                semantic_ranks.insert(h.id.clone(), rank_weight);
                hit_text.insert(h.id, h.text);
            }

            let now_unix = chrono::Utc::now().timestamp();
            let hit_ids: Vec<String> = semantic_ranks.keys().cloned().collect();
            let placeholders = hit_ids.iter().map(|_| "?").collect::<Vec<_>>().join(", ");

            // Hydrate metadata from SQLite using parameterized bindings.
            // Security Note: Only '?' placeholders are dynamically generated in the IN-clause.
            let hydrate_sql = format!(
                r#"SELECT id, text, content_hash, topic, cluster_id, source_node_id,
                          source_agent_id, confidence, ttl, human_confirmed,
                          created_at, access_count,
                          concept_type, title, description, resource_uri, tags, security_tier, parent_id
                   FROM knowledge_store_meta
                   WHERE id IN ({})
                     AND confidence >= ?
                     AND (ttl IS NULL OR ttl > ?)
                     AND (? IS NULL OR topic = ?)
                     AND (? IS NULL OR (? = 'global' AND cluster_id IS NULL) OR (? != 'global' AND (cluster_id = ? OR cluster_id IS NULL)))
                     AND (? IS NULL OR concept_type = ?)
                     AND (? IS NULL OR security_tier = ?)
                   ORDER BY confidence DESC"#,
                placeholders
            );

            let mut q = sqlx::query(sqlx::AssertSqlSafe(&*hydrate_sql));
            for id in &hit_ids {
                q = q.bind(id);
            }
            q = q
                .bind(min_confidence)
                .bind(now_unix)
                .bind(&req.topic)
                .bind(&req.topic)
                .bind(&req.cluster_id)
                .bind(&req.cluster_id)
                .bind(&req.cluster_id)
                .bind(&req.cluster_id)
                .bind(&req.concept_type)
                .bind(&req.concept_type)
                .bind(&req.security_tier)
                .bind(&req.security_tier);

            let rows = q.fetch_all(&self.pool).await.map_err(|e| {
                AppError::InternalServerError(format!("[IKS] search hydration failed: {}", e))
            })?;

            let mut results: Vec<KnowledgeEntry> = rows
                .into_iter()
                .map(|r| {
                    let mut entry = Self::entry_from_row(r).map_err(|e| {
                        AppError::InternalServerError(format!("[IKS] row decode failed: {}", e))
                    })?;
                    // Fall back to LanceDB hit text for pre-migration entries if SQLite text is empty
                    if entry.text.is_empty() {
                        if let Some(t) = hit_text.get(&entry.id) {
                            entry.text = t.clone();
                        }
                    }
                    Ok(entry)
                })
                .collect::<Result<Vec<_>, AppError>>()?;

            // Filter out any entries that ended up with empty text
            results.retain(|e| !e.text.trim().is_empty());

            // Blend semantic rank with confidence + deterministic tie-breaking
            results.sort_by(|a, b| {
                let sim_a = semantic_ranks.get(&a.id).copied().unwrap_or(0.0);
                let sim_b = semantic_ranks.get(&b.id).copied().unwrap_or(0.0);

                let score_a = (if a.human_confirmed {
                    HUMAN_CONFIRMED_SCORE_MULTIPLIER
                } else {
                    1.0
                }) * a.confidence
                    + (SIMILARITY_RANK_WEIGHT * sim_a);

                let score_b = (if b.human_confirmed {
                    HUMAN_CONFIRMED_SCORE_MULTIPLIER
                } else {
                    1.0
                }) * b.confidence
                    + (SIMILARITY_RANK_WEIGHT * sim_b);

                score_b
                    .partial_cmp(&score_a)
                    .unwrap_or(std::cmp::Ordering::Equal)
                    .then_with(|| b.created_at.cmp(&a.created_at))
                    .then_with(|| a.id.cmp(&b.id))
            });

            results.truncate(limit as usize);
            return Ok(results);
        }

        // ── Fallback Path (Non-vector build) ────────────────────────────────
        #[cfg(not(feature = "vector-memory"))]
        {
            let _ = http_client;
            self.search_sqlite_fallback(req, limit, min_confidence)
                .await
        }
    }

    /// Internal SQLite relational search fallback.
    pub(crate) async fn search_sqlite_fallback(
        &self,
        req: &KnowledgeSearchRequest,
        limit: i64,
        min_confidence: f64,
    ) -> Result<Vec<KnowledgeEntry>, AppError> {
        let trimmed_query = req.query.trim();
        let escaped_query = trimmed_query
            .replace('\\', "\\\\")
            .replace('%', "\\%")
            .replace('_', "\\_");
        let query_pattern = format!("%{}%", escaped_query);
        let has_query = !trimmed_query.is_empty();

        let candidate_rows = sqlx::query(
            r#"SELECT id, text, content_hash, topic, cluster_id, source_node_id,
                      source_agent_id, confidence, ttl, human_confirmed,
                      created_at, access_count,
                      concept_type, title, description, resource_uri, tags, security_tier, parent_id
               FROM knowledge_store_meta
               WHERE (? = 0 OR text LIKE ? ESCAPE '\' OR title LIKE ? ESCAPE '\' OR description LIKE ? ESCAPE '\')
                 AND (? IS NULL OR topic = ?)
                 AND (? IS NULL OR (? = 'global' AND cluster_id IS NULL) OR (? != 'global' AND (cluster_id = ? OR cluster_id IS NULL)))
                 AND (? IS NULL OR concept_type = ?)
                 AND (? IS NULL OR security_tier = ?)
                 AND confidence >= ?
                 AND (ttl IS NULL OR ttl > unixepoch())
               ORDER BY confidence DESC, created_at DESC, id ASC
               LIMIT ?"#,
        )
        .bind(if has_query { 1 } else { 0 })
        .bind(&query_pattern)
        .bind(&query_pattern)
        .bind(&query_pattern)
        .bind(&req.topic)
        .bind(&req.topic)
        .bind(&req.cluster_id)
        .bind(&req.cluster_id)
        .bind(&req.cluster_id)
        .bind(&req.cluster_id)
        .bind(&req.concept_type)
        .bind(&req.concept_type)
        .bind(&req.security_tier)
        .bind(&req.security_tier)
        .bind(min_confidence)
        .bind(limit)
        .fetch_all(&self.pool)
        .await
        .map_err(|e| {
            AppError::InternalServerError(format!("[IKS] search (sqlite fallback) failed: {}", e))
        })?;

        let results: Vec<KnowledgeEntry> = candidate_rows
            .into_iter()
            .map(Self::entry_from_row)
            .collect::<Result<Vec<_>, _>>()
            .map_err(|e| {
                AppError::InternalServerError(format!("[IKS] search row decode failed: {}", e))
            })?;

        Ok(results)
    }
}

//! - **Local Errors**: none
//! - **Telemetry Targets**: `[IKS]`
//! - **Witness Tests**: none declared

use super::types::{
    AddKnowledgeRequest, KnowledgeEntry, SecurityTier, DEFAULT_AGENT_CONFIDENCE, DEFAULT_TTL_DAYS,
    MAX_UNCONFIRMED_CONFIDENCE,
};
use crate::error::AppError;
use sqlx::{Row, SqlitePool};
#[cfg(feature = "vector-memory")]
use std::sync::Arc;

pub struct KnowledgeStore {
    pub(crate) pool: SqlitePool,
    #[cfg(feature = "vector-memory")]
    pub(crate) lance: tokio::sync::OnceCell<Arc<crate::agent::memory::VectorMemory>>,
}

impl KnowledgeStore {
    /// Creates a new KnowledgeStore backed by the given SQLite connection pool.
    pub fn new(pool: SqlitePool) -> Self {
        Self {
            pool,
            #[cfg(feature = "vector-memory")]
            lance: tokio::sync::OnceCell::new(),
        }
    }

    /// Lazily initializes and returns the LanceDB vector store connection.
    #[cfg(feature = "vector-memory")]
    pub(super) async fn get_lance(
        &self,
    ) -> Result<Arc<crate::agent::memory::VectorMemory>, AppError> {
        let lance = self
            .lance
            .get_or_try_init(|| async {
                let data_dir = std::env::var("IKS_DATA_DIR")
                    .unwrap_or_else(|_| "data/iks/knowledge_store".to_string());
                let v = crate::agent::memory::VectorMemory::connect(&data_dir, "knowledge_store")
                    .await?;
                Ok::<_, AppError>(Arc::new(v))
            })
            .await?;
        Ok(lance.clone())
    }

    /// Computes a scoped SHA-256 hex hash (topic:cluster:text) for dedup and P2P idempotency.
    pub fn sha256_hash(topic: &str, cluster_id: Option<&str>, text: &str) -> String {
        use sha2::{Digest, Sha256};
        let mut hasher = Sha256::new();
        let scoped_input = format!(
            "{}:{}:{}",
            topic.trim().to_lowercase(),
            cluster_id.unwrap_or("").trim(),
            text.trim()
        );
        hasher.update(scoped_input.as_bytes());
        let result = hasher.finalize();
        hex::encode(result)
    }

    /// Computes the TTL unix timestamp for a new entry.
    /// Q3 decision: agent default = 90d, human-confirmed = NULL (never).
    pub(super) fn compute_ttl(
        human_confirmed: bool,
        ttl_days: Option<i64>,
        now_unix: i64,
    ) -> Option<i64> {
        match (human_confirmed, ttl_days) {
            (true, _) => None,                               // human-confirmed → never expires
            (false, Some(d)) => Some(now_unix + d * 86_400), // caller-supplied
            (false, None) => Some(now_unix + DEFAULT_TTL_DAYS * 86_400), // agent default: 90d
        }
    }

    pub(super) fn entry_from_row(
        row: sqlx::sqlite::SqliteRow,
    ) -> Result<KnowledgeEntry, sqlx::Error> {
        let sec_tier_str: String = row
            .try_get("security_tier")
            .unwrap_or_else(|_| "BRONZE_ADHOC".to_string());
        let security_tier = SecurityTier::from_str_lossless(&sec_tier_str)
            .as_str()
            .to_string();

        Ok(KnowledgeEntry {
            id: row.try_get("id")?,
            text: row.try_get("text")?,
            topic: row.try_get("topic")?,
            cluster_id: row.try_get("cluster_id")?,
            source_node_id: row.try_get("source_node_id")?,
            source_agent_id: row.try_get("source_agent_id")?,
            content_hash: row.try_get("content_hash")?,
            confidence: row.try_get::<f64, _>("confidence")? as f32,
            human_confirmed: row.try_get::<i64, _>("human_confirmed")? != 0,
            ttl: row.try_get("ttl")?,
            created_at: row.try_get("created_at")?,
            access_count: row.try_get("access_count")?,
            concept_type: row.try_get("concept_type")?,
            title: row.try_get("title")?,
            description: row.try_get("description")?,
            resource_uri: row.try_get("resource_uri")?,
            tags: row.try_get("tags")?,
            security_tier,
            parent_id: row.try_get("parent_id").ok(),
        })
    }

    /// Internal lookup by content hash without tracking access.
    pub async fn get_by_hash(
        &self,
        content_hash: &str,
    ) -> Result<Option<KnowledgeEntry>, AppError> {
        let row = sqlx::query(
            r#"SELECT id, text, content_hash, topic, cluster_id, source_node_id,
                      source_agent_id, confidence, ttl, human_confirmed,
                      created_at, access_count,
                      concept_type, title, description, resource_uri, tags, security_tier, parent_id
               FROM knowledge_store_meta WHERE content_hash = ? LIMIT 1"#,
        )
        .bind(content_hash)
        .fetch_optional(&self.pool)
        .await
        .map_err(|e| AppError::InternalServerError(format!("[IKS] get_by_hash failed: {}", e)))?;

        row.map(Self::entry_from_row)
            .transpose()
            .map_err(|e| AppError::InternalServerError(format!("[IKS] row decode failed: {}", e)))
    }

    /// Write a new knowledge entry.
    ///
    /// Deduplicates by scoped `content_hash` (topic:cluster:text) — returns existing entry
    /// unchanged if identical knowledge already exists.
    ///
    /// Agent submissions default to confidence 0.70 (capped at 0.80) and 90-day TTL.
    /// Human confirmation can only be set via the human-authenticated `confirm(id)` route.
    pub async fn add_entry(
        &self,
        req: AddKnowledgeRequest,
        #[allow(unused_variables)] http_client: reqwest::Client,
    ) -> Result<KnowledgeEntry, AppError> {
        if req.text.trim().is_empty() {
            return Err(AppError::BadRequest(
                "Knowledge text cannot be empty".to_string(),
            ));
        }

        if let Some(d) = req.ttl_days {
            if !(1..=3650).contains(&d) {
                return Err(AppError::BadRequest(
                    "ttl_days must be between 1 and 3650".to_string(),
                ));
            }
        }

        // ── Privacy guard ──────────────────────────────────────────────────
        let privacy_mode = std::env::var("PRIVACY_MODE")
            .map(|v| v.to_lowercase() == "true" || v == "1")
            .unwrap_or(false);
        if privacy_mode {
            tracing::warn!(
                topic = %req.topic,
                "[IKS] PRIVACY_MODE active — rejecting knowledge store write"
            );
            return Err(AppError::Conflict(
                "[IKS] Writes disabled while PRIVACY_MODE is active".to_string(),
            ));
        }

        // ── Dedup check ────────────────────────────────────────────────────
        let content_hash = Self::sha256_hash(&req.topic, req.cluster_id.as_deref(), &req.text);
        if let Some(existing) = self.get_by_hash(&content_hash).await? {
            tracing::debug!(id = %existing.id, "[IKS] Dedup hit — returning existing entry");
            return Ok(existing);
        }

        // ── Compute embedding ──────────────────────────────────────────────
        #[cfg(feature = "vector-memory")]
        let vector = {
            let api_key = std::env::var("GOOGLE_API_KEY").map_err(|_| {
                AppError::BadRequest(
                    "[IKS] GOOGLE_API_KEY required for embedding. Set it in .env.".to_string(),
                )
            })?;
            crate::agent::memory::get_gemini_embedding(&http_client, &api_key, &req.text).await?
        };

        // ── Prepare metadata ───────────────────────────────────────────────
        let id = uuid::Uuid::new_v4().to_string();
        let now_unix = chrono::Utc::now().timestamp();
        // Agent writes are always unconfirmed at creation time
        let human_confirmed = false;
        let confidence = req
            .confidence
            .unwrap_or(DEFAULT_AGENT_CONFIDENCE)
            .clamp(0.0, MAX_UNCONFIRMED_CONFIDENCE);
        let ttl = Self::compute_ttl(human_confirmed, req.ttl_days, now_unix);
        let topic = req.topic.trim().to_lowercase();
        let concept_type = req
            .concept_type
            .unwrap_or_else(|| "general".to_string())
            .trim()
            .to_lowercase();
        let security_tier = req
            .security_tier
            .as_deref()
            .map(SecurityTier::from_str_lossless)
            .unwrap_or_default()
            .as_str()
            .to_string();

        // ── SQLite Transaction with Atomic ON CONFLICT ───────────────────────
        let mut tx = self.pool.begin().await.map_err(|e| {
            AppError::InternalServerError(format!("[IKS] Failed to start transaction: {}", e))
        })?;

        let insert_res = sqlx::query(
            r#"INSERT INTO knowledge_store_meta
               (id, text, content_hash, topic, cluster_id, source_node_id, source_agent_id,
                confidence, ttl, human_confirmed, created_at, updated_at,
                concept_type, title, description, resource_uri, tags, security_tier, parent_id)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?, ?, ?, ?, ?, ?, ?, ?)
               ON CONFLICT(content_hash) DO NOTHING"#,
        )
        .bind(&id)
        .bind(&req.text)
        .bind(&content_hash)
        .bind(&topic)
        .bind(&req.cluster_id)
        .bind(&req.source_node_id)
        .bind(&req.source_agent_id)
        .bind(confidence as f64)
        .bind(ttl)
        .bind(now_unix)
        .bind(now_unix)
        .bind(&concept_type)
        .bind(&req.title)
        .bind(&req.description)
        .bind(&req.resource_uri)
        .bind(&req.tags)
        .bind(&security_tier)
        .bind(&req.parent_id)
        .execute(&mut *tx)
        .await
        .map_err(|e| AppError::InternalServerError(format!("[IKS] SQLite insert failed: {}", e)))?;

        // If another thread inserted the exact same content_hash concurrently:
        if insert_res.rows_affected() == 0 {
            let _ = tx.rollback().await;
            if let Some(existing) = self.get_by_hash(&content_hash).await? {
                return Ok(existing);
            }
            return Err(AppError::InternalServerError(
                "[IKS] Concurrent insert conflict resolution failed".to_string(),
            ));
        }

        // ── Insert LanceDB vector row ──────────────────────────────────────
        #[cfg(feature = "vector-memory")]
        {
            let lance = self.get_lance().await?;
            lance.ensure_table().await?;
            if let Err(e) = lance.add_memory(&id, &req.text, &topic, vector).await {
                let _ = tx.rollback().await;
                return Err(AppError::InternalServerError(format!(
                    "[IKS] LanceDB insert failed: {}",
                    e
                )));
            }
        }

        // Commit SQLite metadata
        tx.commit().await.map_err(|e| {
            AppError::InternalServerError(format!("[IKS] Transaction commit failed: {}", e))
        })?;

        tracing::info!(
            id = %id,
            topic = %topic,
            human_confirmed = false,
            "[IKS] New knowledge entry stored"
        );

        Ok(KnowledgeEntry {
            id,
