fn invalid_conductor_plan(detail: impl Into<String>) -> AppError {
    AppError::InfrastructureError {
        provider_id: crate::error::ProviderId::Runner,
        kind: crate::error::InfrastructureErrorKind::Other,
        detail: detail.into(),
