/// Resolves the file path argument from a tool call, accepting both `path` and
/// `filename` as valid keys. Agents occasionally emit `filename` instead of
/// `path`; this alias prevents a hard `[FAILURE]` on an otherwise valid call.
///
/// Priority: `path` is checked first; `filename` is used as a fallback.
fn require_path(
    ctx: &RunContext,
    args: &serde_json::Value,
    tool_name: &str,
) -> Result<String, ToolExecutionError> {
    // Prefer the canonical "path" key
    if args
        .get("path")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
        .is_some()
    {
        return require_str(ctx, args, "path", tool_name);
    }
    // Fall back to "filename" alias (commonly produced by LLM outputs)
    if args
        .get("filename")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
        .is_some()
    {
        tracing::debug!(
            "[codebase] Agent {} used 'filename' alias instead of 'path' in '{}'. Accepting.",
            ctx.agent_id,
            tool_name
        );
        return require_str(ctx, args, "filename", tool_name);
    }
    // Neither key present — delegate to require_str for a canonical error message
    require_str(ctx, args, "path", tool_name)
}

