                            .unwrap_or(false);

                    if is_initiator_coo {
                        coo_approved = true;
                    } else {
                        // Gate 1: COO Approval Check
                        let coo_agent = self
                            .state
                            .registry
                            .agents
                            .get(AGENT_ALPHA)
                            .or_else(|| self.state.registry.agents.get(AGENT_COO));

                        let mut coo_available = false;
                        if let Some(coo_ref) = coo_agent {
                            let coo = coo_ref.value();
                            if coo.health.status != "suspended" {
                                coo_available = true;
                                let mut coo_ctx = coo.resolve_provider_context(
                                    self.state.base_dir.clone(),
                                    ctx.cluster_id.as_deref(),
