                            "role": agent.identity.role,
                            "coo_rationale": coo_rationale
                        }),
                        department: "governance".to_string(),
                        description: format!(
                            "Authorize reactivation of suspended agent '{}' ({})",
                            agent.identity.name, agent.identity.id
                        ),
                        timestamp: chrono::Utc::now().to_rfc3339(),
