                            agent.identity.id
                        )));
                    }

                    tracing::info!(
                        "⚖️ [Governance] Reactivation of '{}' approved; persistence will occur in the short recruitment transaction.",
                        agent.identity.id
                    );
                }
            }
        }
        Ok(())
    }
