pub fn get_hierarchy_label(level: RoleAuthorityLevel) -> &'static str {
    match level {
        RoleAuthorityLevel::Executive => "EXECUTIVE (Tier 0)",
        RoleAuthorityLevel::Management => "ORCHESTRATOR (Tier 1)",
        RoleAuthorityLevel::Specialist => "SPECIALIST (Tier 2)",
        RoleAuthorityLevel::Observer => "AUDITOR (Tier 3)",
    }
}

/// Checks if an execution context has orchestrator/commander authority.
pub fn is_orchestrator(ctx: &RunContext) -> bool {
    ctx.agent_id == AGENT_CEO
        || ctx.agent_id == AGENT_COO
        || ctx.agent_id == AGENT_ALPHA
        || ctx.authority_level == RoleAuthorityLevel::Executive
        || ctx.authority_level == RoleAuthorityLevel::Management
        || {
            let role_lower = ctx.role.to_lowercase();
            role_lower.contains("alpha")
                || role_lower.contains("commander")
                || role_lower.contains("coo")
                || role_lower.contains("ceo")
                || role_lower.contains("cto")
        }
}

pub fn generate_swarm_protocols(ctx: &RunContext, state: &AppState) -> String {
    let mut swarm_protocols =
        state
            .resources
            .acl
            .get_role_protocols(&ctx.agent_id, &ctx.role, ctx.authority_level);

    // Add shared/invariant swarm rules
    swarm_protocols.push("NO NARRATION: Do not explain strategy or tool options. CALL THE TOOLS. Text-only responses are MISSION FAILURE.".to_string());
    swarm_protocols
        .push("COMPLETION: Complete ALL steps autonomously before reporting back.".to_string());
    swarm_protocols.push("OVERSIGHT TRUST: Never ask for permission. The system handles approval flows automatically.".to_string());
    swarm_protocols.push("SOURCE OF TRUTH: Prioritize codebase tools (read_codebase_file) over general RAG for code queries.".to_string());
    swarm_protocols.push("TOKEN HYGIENE: For large codebase files (>100 lines), you MUST use 'grep_search' or 'list_file_symbols' (Phase 1) to identify target line ranges first, then use 'read_codebase_file' or 'read_file' with 'start_line' and 'end_line' specified (Phase 2). Reading entire large files directly is FORBIDDEN and causes context collapse. NOTE: 'list_file_symbols' and 'get_symbol_body' only accept paths to individual source files; passing directory paths will result in an Access Denied error. Use 'list_files' or 'grep_search' for directories.".to_string());
    swarm_protocols.push(format!("RECURSION PROTECTION: You are FORBIDDEN from recruiting agents in your LINEAGE ({:?}) or YOURSELF ({}).", ctx.lineage, ctx.agent_id));

    // Delegation Mandate for Orchestrators/Commanders lacking direct shell execution permissions
    if !ctx.skills.contains(&"execute_shell".to_string()) && is_orchestrator(ctx) {
        swarm_protocols.push(
            "DELEGATION MANDATE: As Swarm Commander/Orchestrator, direct shell ('execute_shell') and file search ('grep_search') tools are restricted for your role. You MUST use 'spawn_subagent' or 'send_mission_directive' to recruit or delegate file and shell operations to specialized execution worker nodes (e.g. 'coder' or 'audit_specialist').".to_string(),
        );
    }

    swarm_protocols
        .iter()
        .enumerate()
        .map(|(i, p)| format!("{}. {}", i + 1, p))
        .collect::<Vec<_>>()
        .join("\n")
}

/// Container for structural components of the system prompt.
#[derive(Debug, Clone)]
pub struct StructuralComponents {
    pub cluster_directory: String,
    pub filesystem_bias_mandate: String,
    pub lineage_display: String,
    pub is_orchestrator: bool,
    pub safe_mode_prefix: String,
    pub tool_mode_prefix: String,
}

pub fn generate_structural_components(ctx: &RunContext, state: &AppState) -> StructuralComponents {
    let cluster_specialists = state.registry.list_active_specialists();
    let orchestrator_flag = is_orchestrator(ctx);

    // --- Cluster Directory ---
    let cluster_directory = if cluster_specialists.is_empty() {
        "No specialized agents currently registered in the cluster pool. You are encouraged to recruit a NEW specialist ID (e.g. 'researcher', 'coder') if needed.".to_string()
    } else {
        cluster_specialists
            .into_iter()
            .map(|id| {
                if orchestrator_flag {
                    id
                } else {
                    match id.as_str() {
                        AGENT_CEO => "[SYSTEM_EXECUTIVE]".to_string(),
                        AGENT_COO => "[SYSTEM_ORCHESTRATOR]".to_string(),
                        AGENT_ALPHA => "[SYSTEM_COMMANDER]".to_string(),
                        other => other.to_string(),
                    }
                }
            })
            .collect::<Vec<_>>()
            .join("\n")
    };

    // --- Mission Bias ---
    let filesystem_bias_mandate = if has_file_system_capability(ctx) {
        "DATA_ACCESS: PERMITTED. You represent a specialist with localized I/O authority."
            .to_string()
    } else {
        "DATA_ACCESS: RESTRICTED. Direct filesystem mutation is disabled. Use swarm recruitment for I/O.".to_string()
    };

    // --- Lineage Display ---
    let lineage_display = if ctx.lineage.is_empty() {
        "None (You are the root node)".to_string()
    } else {
        let path_parts: Vec<String> = ctx
            .lineage
            .iter()
            .map(|id| {
                if orchestrator_flag {
                    id.clone()
                } else {
                    match id.as_str() {
                        AGENT_CEO => "EXECUTIVE".to_string(),
                        AGENT_COO => "ORCHESTRATOR".to_string(),
                        AGENT_ALPHA => "COMMANDER".to_string(),
                        _ => id.clone(),
                    }
                }
            })
            .collect();
        path_parts.join(" -> ")
    };

    // --- Prefixes ---
    let safe_mode_prefix = if ctx.safe_mode {
        "🔒 TOOLS FORBIDDEN: You are in CONVERSATIONAL MODE. Do NOT attempt to call any tools. \
         Respond directly with natural language. \
         Be helpful, insightful, and conversational. No tool calls, no mission completion — just talk.\n".to_string()
    } else {
        "🔓 SECURITY: ACTIVE. You have authority to propose and execute mutations within your workspace scope.\n".to_string()
    };

    let tool_mode_prefix = if ctx.analysis {
        "🛠️ TOOL EVOLUTION: You are in ANALYSIS mode. Propose architectural changes.".to_string()
    } else {
        "⚙️ TOOL REFINEMENT: Standard operation.".to_string()
    };

    StructuralComponents {
        cluster_directory,
        filesystem_bias_mandate,
        lineage_display,
        is_orchestrator: orchestrator_flag,
        safe_mode_prefix,
        tool_mode_prefix,
    }
}

pub fn has_file_system_capability(ctx: &RunContext) -> bool {
    ctx.skills.iter().any(|s| {
        s == "filesystem"
            || s == "read_file"
            || s == "write_file"
            || s == "list_files"
            || s == "delete_file"
    })
}

