                    )
                } else {
                    format!(
                        " Authorized skills in your allowlist: {:?}.",
                        allowed_skills
                    )
                };

                return Err(ToolExecutionError::SecurityBlocked(format!(
                    "Skill '{}' not in agent allowlist.{}",
                    fc.name, suggestion
                )));
