#[derive(Parser, Debug)]
#[command(
    name = "graph_query",
    about = "Scriptable symbol graph queries for coding agents and audits"
)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Commands,
}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Export the full symbol graph
    Export {
        #[arg(long, default_value = ".")]
        root: PathBuf,
        #[arg(long)]
        out: Option<PathBuf>,
        #[arg(long)]
        pretty: bool,
    },
    /// Generate high-connectivity audit context
    AuditContext {
        #[arg(long, default_value = ".")]
        root: PathBuf,
        #[arg(long)]
        out: Option<PathBuf>,
        #[arg(long, default_value_t = 20, value_parser = clap::value_parser!(u32).range(1..1000))]
        limit: u32,
    },
    /// Lookup symbols by name
    Lookup {
        #[arg(long)]
        name: String,
        #[arg(long, default_value = ".")]
        root: PathBuf,
        #[arg(long, default_value_t = 20, value_parser = clap::value_parser!(u32).range(1..1000))]
        limit: u32,
        #[arg(long)]
        json: bool,
        #[arg(long)]
        out: Option<PathBuf>,
    },
    /// Query symbol context for a specific file path
    File {
        #[arg(long)]
        path: String,
        #[arg(long, default_value = ".")]
        root: PathBuf,
        #[arg(long, default_value_t = 20, value_parser = clap::value_parser!(u32).range(1..1000))]
        limit: u32,
        #[arg(long)]
        json: bool,
        #[arg(long)]
        out: Option<PathBuf>,
    },
    /// Calculate the blast radius of a symbol in a file
    Blast {
        #[arg(long)]
        name: String,
        #[arg(long)]
        path: String,
        #[arg(long, default_value = ".")]
        root: PathBuf,
        #[arg(long)]
        json: bool,
        #[arg(long)]
        out: Option<PathBuf>,
        #[arg(long, default_value_t = 50, value_parser = clap::value_parser!(u32).range(1..1000))]
        depth: u32,
        #[arg(long, default_value = "text", value_parser = ["text", "mermaid", "html"])]
        format: String,
    },
    /// Validate backticked symbols inside docstrings against the graph connections
    Validate {
        #[arg(long, default_value = ".")]
        root: PathBuf,
        #[arg(long)]
        strict: bool,
        #[arg(long)]
        out: Option<PathBuf>,
