pub mod metadata;
mod rfc9457;

// Re-export all public types so `use crate::error::AppError` continues to work.
pub use metadata::{ErrorMetadata, HasErrorMetadata, Severity};

use axum::http::StatusCode;
use serde::{Deserialize, Serialize};
use thiserror::Error;

const ALLOWED_HELP_PREFIXES: &[&str] = &[
    "https://tadpole.os/",
    "https://docs.tadpole.os/",
    "https://console.cloud.google.com/",
];

/// Helper function to safely truncate a string to a maximum number of bytes
/// without breaking UTF-8 char boundaries.
pub fn safe_truncate_bytes(s: &str, max_bytes: usize) -> String {
    if s.len() > max_bytes {
        let mut end = max_bytes.saturating_sub(3);
        while end > 0 && !s.is_char_boundary(end) {
            end -= 1;
        }
        let mut truncated = s[..end].to_string();
        truncated.push_str("...");
        truncated
    } else {
        s.to_string()
    }
}

/// Helper function to sanitize HTML characters to prevent XSS payloads.
fn sanitize_html(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&#x27;")
}

/// Helper function to validate if a help_link is public and safe.
fn is_public_and_safe_link(url: &str) -> bool {
    let lower_url = url.to_ascii_lowercase();
    ALLOWED_HELP_PREFIXES
        .iter()
        .any(|prefix| lower_url.starts_with(prefix))
}

/// Helper function to format a list of errors.
fn format_errors(errors: &[AppError]) -> String {
    errors
        .iter()
        .map(|e| e.to_string())
        .collect::<Vec<_>>()
        .join("; ")
}

/// RFC 9457 (Problem Details for HTTP APIs) compliant error structure.
#[derive(Debug, Serialize)]
pub struct ProblemDetails {
    #[serde(rename = "type")]
    pub type_uri: String,
    pub title: String,
    pub status: u16,
    pub detail: String,
    pub instance: Option<String>,
    pub error_code: Option<String>,
    pub help_link: Option<String>,
    pub severity: Severity,
}

impl ProblemDetails {
    /// Centralized builder for ProblemDetails that enforces secret redaction,
    /// HTML sanitization, bounded truncation, and internal error masking.
    /// Invariant: 1) Redact raw secrets -> 2) HTML sanitize -> 3) Bounded truncation <= 2048 bytes.
    pub fn build(
        status: StatusCode,
        slug: &str,
        detail: String,
        help_link: Option<String>,
        severity: Severity,
        error_code: Option<String>,
        title_override: Option<String>,
        instance: Option<String>,
    ) -> Self {
        let is_server_err = status.is_server_error();
        let detail_to_process = if is_server_err {
            "An internal server error occurred. Please check system logs.".to_string()
        } else {
            detail
        };

        // Enforce ordering: Redact raw secrets first, sanitize HTML entities, then enforce byte cap
        let scrubbed = crate::utils::security::redact_secrets(&detail_to_process);
        let sanitized = sanitize_html(&scrubbed);
        let truncated = safe_truncate_bytes(&sanitized, 2048);

        let encoded_slug = urlencoding::encode(slug).into_owned();
        let title = title_override.unwrap_or_else(|| slug.replace(['-', ':'], " ").to_uppercase());

        let safe_help_link = help_link.filter(|link| is_public_and_safe_link(link));

        Self {
            type_uri: format!("https://tadpole.os/errors/{}", encoded_slug),
            title,
            status: status.as_u16(),
            detail: truncated,
            instance,
            error_code: error_code.or_else(|| Some(slug.to_uppercase().replace(['-', ':'], "_"))),
            help_link: safe_help_link,
            severity,
        }
    }

    /// Creates a new ProblemDetails instance configured from status and title.
    pub fn new(status: StatusCode, title: &str, detail: String) -> Self {
        let slug = title.to_lowercase().replace(' ', "-");
        let severity = if status.is_server_error()
            || status == StatusCode::FORBIDDEN
            || status == StatusCode::UNAUTHORIZED
        {
            Severity::Critical
        } else {
            Severity::Error
        };

        Self::build(
            status,
            &slug,
            detail,
            None,
            severity,
            Some(slug.to_uppercase().replace(['-', ':'], "_")),
            Some(title.to_string()),
            None,
        )
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum DomainCode {
    InsufficientQuota,
    InvalidConfiguration,
    AgentDeactivated,
    InvalidStateTransition,
    OversightViolation,
    TaskConflict,
    SystemError,
}

impl std::fmt::Display for DomainCode {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let s = match self {
            DomainCode::InsufficientQuota => "insufficient-quota",
            DomainCode::InvalidConfiguration => "invalid-configuration",
            DomainCode::AgentDeactivated => "agent-deactivated",
            DomainCode::InvalidStateTransition => "invalid-state-transition",
            DomainCode::OversightViolation => "oversight-violation",
            DomainCode::TaskConflict => "task-conflict",
            DomainCode::SystemError => "system-error",
        };
        write!(f, "{}", s)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum ProviderId {
    Anthropic,
    OpenAi,
    Gemini,
    Groq,
    Deepseek,
    Openrouter,
    Mistral,
    Xai,
    Ollama,
    Mcp,
    Audio,
    Runner,
    System,
}

impl ProviderId {
    pub fn from_name(name: &str) -> Self {
        match name.to_ascii_lowercase().trim() {
            "anthropic" => ProviderId::Anthropic,
            "openai" => ProviderId::OpenAi,
            "gemini" | "google" => ProviderId::Gemini,
            "groq" => ProviderId::Groq,
            "deepseek" => ProviderId::Deepseek,
            "openrouter" => ProviderId::Openrouter,
            "mistral" => ProviderId::Mistral,
            "xai" => ProviderId::Xai,
            "ollama" | "ollama-cloud" => ProviderId::Ollama,
            "mcp" => ProviderId::Mcp,
            "audio" => ProviderId::Audio,
            "runner" => ProviderId::Runner,
            other => {
                tracing::warn!(provider = %other, "Unrecognized provider identifier fallback to System");
                ProviderId::System
            }
        }
    }
}

impl std::fmt::Display for ProviderId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let s = match self {
            ProviderId::Anthropic => "anthropic",
