        }
    };

    if let Some(stored) = persisted {
        if stored != SCHEMA_VERSION {
            tracing::warn!(
                "⚠️ [db] Schema version mismatch (stored={}, current={}). Recreating tables.",
                stored,
                SCHEMA_VERSION
            );
            let drop_stmts = [
                "DROP TABLE IF EXISTS flow_memberships",
                "DROP TABLE IF EXISTS flow_snapshots",
