    "if", "while", "for", "switch", "match", "catch", "else", "return", "sizeof", "typeof",
    "require",
];

pub trait LanguageProcessor: Send + Sync {
    fn extract(
        &self,
        extractor: &mut SymbolExtractor,
        path: &Path,
        content: &str,
    ) -> Result<(Vec<SymbolRecord>, Vec<Reference>, Vec<String>), AppError>;
}

pub struct AstProcessor;
impl LanguageProcessor for AstProcessor {
    fn extract(
        &self,
        extractor: &mut SymbolExtractor,
        path: &Path,
        content: &str,
    ) -> Result<(Vec<SymbolRecord>, Vec<Reference>, Vec<String>), AppError> {
        let symbols = extractor
            .extract_symbols(path, content)
            .into_iter()
            .map(symbol_to_record)
            .collect();
        let refs = extractor.extract_references(path, content);
        let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
        let imports = extract_imports(ext, content);
        Ok((symbols, refs, imports))
    }
}

pub struct RegexProcessor;
impl LanguageProcessor for RegexProcessor {
    fn extract(
        &self,
        _extractor: &mut SymbolExtractor,
        path: &Path,
        content: &str,
    ) -> Result<(Vec<SymbolRecord>, Vec<Reference>, Vec<String>), AppError> {
        let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
        Ok(lightweight_extract(ext, content))
    }
}

pub fn lookup_processor(ext: &str) -> Option<&'static dyn LanguageProcessor> {
    static AST_PROC: AstProcessor = AstProcessor;
    static REGEX_PROC: RegexProcessor = RegexProcessor;

    match ext {
        "rs" | "ts" | "tsx" => Some(&AST_PROC),
        "py" | "sql" | "js" | "cjs" | "mjs" | "ps1" | "sh" => Some(&REGEX_PROC),
        // Unsupported extensions fall back to empty extraction
        _ => None,
    }
}

fn symbol_to_record(sym: Symbol) -> SymbolRecord {
    SymbolRecord {
        name: sym.name,
        kind: sym.kind,
        line_start: (sym.range.start_line as i64).saturating_add(1),
        line_end: (sym.range.end_line as i64).saturating_add(1),
        signature: sym.signature,
        parent_name: None,
        params: None,
        return_type: None,
        modifiers: None,
    }
}

/// Extracts symbols, references, and imports using simple regex patterns.
///
///

//! - **Local Errors**: none
//! - **Telemetry Targets**: none declared
//! - **Witness Tests**: `intelligence::graph_store::heuristics::tests`

use super::model::{FileRecord, NodeRow, SymbolKind, SymbolRecord};
use crate::utils::parser::Reference;
use std::collections::{HashMap, HashSet};
use std::sync::Arc;

pub fn normalize_kind(kind: &str, is_test: bool) -> SymbolKind {
    if is_test {
        return SymbolKind::Test;
    }
    match kind {
        "struct" | "enum" | "trait" | "class" | "interface" | "type" | "impl" => SymbolKind::Class,
        _ => SymbolKind::Function,
    }
}

pub fn language_for_ext(ext: &str) -> &'static str {
    match ext {
        "rs" => "rust",
        "ts" => "typescript",
        "tsx" => "tsx",
        "py" => "python",
        "sql" => "sql",
        "ps1" => "powershell",
        "sh" => "bash",
        _ => "javascript",
    }
}

pub fn is_test_path(path: &str) -> bool {
    let lower = path.to_lowercase().replace('\\', "/");
    lower.contains(".test.")
        || lower.contains("_test.")
        || lower.contains("_tests.")
        || lower.contains("/tests/")
        || lower.ends_with("/tests.rs")
        || lower.ends_with(".tests.rs")
        || lower.ends_with("/test.rs")
}

pub fn is_security_relevant(node: &NodeRow) -> bool {
    const TERMS: &[&str] = &[
        "auth",
        "crypto",
        "token",
        "secret",
        "permission",
        "policy",
        "shell",
        "command",
        "process",
        "route",
        "persist",
        "db",
        "network",
        "provider",
        "execute",
        "tool",
        "quota",
        "acl",
        "key",
    ];
    let name_lower = node.name.to_lowercase();
    let path_lower = node.file_path.to_lowercase();
    let sig_lower = node.signature.to_lowercase();

    let haystack = format!("{name_lower} {path_lower} {sig_lower}");
    let tokens: HashSet<&str> = haystack
        .split(|c: char| !c.is_alphanumeric())
        .filter(|s| !s.is_empty())
        .collect();

    TERMS.iter().any(|term| tokens.contains(term))
}

pub fn qualified(file_path: &str, symbol: &str) -> String {
    format!("{file_path}::{symbol}")
}

pub fn qualified_symbol(file_path: &str, symbol: &SymbolRecord) -> String {
    format!(
        "{}@{}-{}",
        qualified(file_path, &symbol.name),
        symbol.line_start,
        symbol.line_end
    )
}

pub fn tightest_symbol<'a>(
    file: &'a FileRecord,
    reference: &Reference,
) -> Option<&'a SymbolRecord> {
    file.symbols
        .iter()
        .filter(|sym| {
            (reference.range.start_line as i64).saturating_add(1) >= sym.line_start
                && (reference.range.end_line as i64).saturating_add(1) <= sym.line_end
        })
        .min_by_key(|sym| sym.line_end - sym.line_start)
}

pub fn match_targets(name: &str, by_name: &HashMap<Arc<str>, Vec<Arc<str>>>) -> Vec<Arc<str>> {
    let direct = name.rsplit([':', '/', '.', '\\']).next().unwrap_or(name);
    by_name.get(direct).cloned().unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_is_test_path_boundaries() {
        assert!(is_test_path("server-rs/src/tests/auth.rs"));
        assert!(is_test_path("server-rs/src/auth.test.ts"));
        assert!(is_test_path("server-rs/src/auth_test.go"));
        assert!(is_test_path("server-rs/tests.rs"));
        assert!(is_test_path("server-rs\\sub\\tests.rs"));

        // Negative cases (false positives avoided)
        assert!(!is_test_path("server-rs/src/contests.rs"));
        assert!(!is_test_path("server-rs/src/protests.rs"));
        assert!(!is_test_path("server-rs/src/latest.rs"));
    }

    #[test]
    fn test_is_security_relevant_token_matching() {
        let make_node = |name: &str, path: &str, sig: &str| NodeRow {
            id: 1,
            kind: "Function".to_string(),
            name: name.to_string(),
            qualified_name: format!("{path}::{name}"),
            file_path: path.to_string(),
            line_start: Some(1),
            line_end: Some(5),
            language: "rust".to_string(),
            parent_name: None,
            params: None,
            return_type: None,
            modifiers: None,
            is_test: false,
            file_hash: "hash".to_string(),
            extra: "{}".to_string(),
            signature: sig.to_string(),
            community_id: None,
        };

        // Positive security hits
        assert!(is_security_relevant(&make_node(
            "validate_token",
            "src/auth.rs",
            "fn validate_token()"
        )));
        assert!(is_security_relevant(&make_node(
            "execute_cmd",
            "src/shell.rs",
            "fn execute_cmd()"
        )));
        assert!(is_security_relevant(&make_node(
            "open_db_pool",
            "src/db.rs",
            "fn open_db_pool()"
        )));

        // Negative cases (substring containment without word boundaries)
        assert!(!is_security_relevant(&make_node(
            "monkey",
            "src/animals.rs",
            "fn monkey()"
        )));
        assert!(!is_security_relevant(&make_node(
            "render_toolbar",
            "src/ui.rs",
            "fn render_toolbar()"
        )));
        assert!(!is_security_relevant(&make_node(
            "fdb_sync",
            "src/sync.rs",
            "fn fdb_sync()"
        )));
    }
}

