    assert_eq!(reset_res.status(), StatusCode::OK);

    let agent_entry = state.registry.agents.get("agent-lifecycle").unwrap();
    assert_eq!(agent_entry.health.failure_count, 0);
    assert_eq!(agent_entry.health.status, "idle");
}

