mod tests {

    #[test]
    fn test_path_boundary_safety() {
        let temp = tempfile::tempdir().unwrap();
        let base = temp.path().to_path_buf();

        let malicious = "../../../etc/shadow";
        assert!(crate::utils::security::validate_path(&base, malicious).is_err());
    }
}

