#[cfg(feature = "vector-memory")]
fn memory_entries_from_batch(
    batch: &arrow_array::RecordBatch,
) -> Result<Vec<MemoryEntry>, AppError> {
    use arrow_array::{Int64Array, StringArray};

    let id_col = batch
        .column_by_name("id")
        .and_then(|c| c.as_any().downcast_ref::<StringArray>())
        .ok_or_else(|| {
            AppError::InternalServerError("Missing 'id' column in memory batch".to_string())
        })?;

    let text_col = batch
        .column_by_name("text")
        .and_then(|c| c.as_any().downcast_ref::<StringArray>())
        .ok_or_else(|| {
            AppError::InternalServerError("Missing 'text' column in memory batch".to_string())
        })?;

    let mission_col = batch
        .column_by_name("mission_id")
        .and_then(|c| c.as_any().downcast_ref::<StringArray>())
        .ok_or_else(|| {
            AppError::InternalServerError("Missing 'mission_id' column in memory batch".to_string())
        })?;

    let ts_col = batch
        .column_by_name("timestamp")
        .and_then(|c| c.as_any().downcast_ref::<Int64Array>())
        .ok_or_else(|| {
            AppError::InternalServerError("Missing 'timestamp' column in memory batch".to_string())
        })?;

    let mut entries = Vec::with_capacity(batch.num_rows());
    for i in 0..batch.num_rows() {
        entries.push(MemoryEntry {
            id: id_col.value(i).to_string(),
            text: text_col.value(i).to_string(),
            mission_id: mission_col.value(i).to_string(),
            timestamp: ts_col.value(i),
        });
    }
    Ok(entries)
}

