pub const ALLOWED_SKILL_EXTENSIONS: &[&str] = &["json", "py", "js", "ts", "sh", "ps1", "bat", "md"];

pub fn is_allowed_skill_extension(ext: &str) -> bool {
    ALLOWED_SKILL_EXTENSIONS.contains(&ext.to_lowercase().as_str())
