#[derive(Debug, Clone)]
pub struct ValidatedAgent {
    pub safe_filename: String,
    pub agent: crate::agent::types::EngineAgent,
    pub serialized: Vec<u8>,
}

#[derive(Debug)]
pub struct ValidatedTemplateAssets {
