            .unwrap();
        let e2 = audit
            .record("agent-1", None, None, "action-2", "{}")
            .await
            .unwrap();
        assert!(audit.verify_chain(None).await.unwrap());

        // Tamper with action.
        sqlx::query("UPDATE audit_trail SET action = 'tampered' WHERE id = ?")
            .bind(&e2.id)
            .execute(&audit.pool)
            .await
            .unwrap();

