#[allow(dead_code)]
pub const MANIFEST_MAGIC_HEADER: &[u8] = b"SEC-05-V1\0";

#[allow(dead_code)]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub enum ManifestStatus {
