    themeColor: string;
    isNew: boolean;
    agentId?: string;
    availableRoles: string[];
    onClose: () => void;
    onDetach?: () => void;
    onDelete?: () => void;
    onUpdateIdentity: (field: 'name' | 'role' | 'department', value: string) => void;
    onUpdateThemeColor: (color: string) => void;
    onRoleChange: (role: string) => void;
    isDetached?: boolean;
}

