                                type="color"
                                value={safeThemeColor}
                                onChange={(e) => onUpdateThemeColor(e.target.value)}
                                className="absolute inset-0 opacity-0 cursor-pointer w-full h-full"
                                aria-label={i18n.t('agent_config.aria_theme_color')}
                            />
