                                    className="absolute inset-y-0 left-0 transition-all duration-700 ease-out"
                                    style={{ 
                                        width: `${daily_spend_limit > 0 ? Math.min((daily_spent_accumulated / daily_spend_limit) * 100, 100) : 0}%`,
