                    </div>
                </div>

                <div className="flex items-center justify-between py-1 border-b border-zinc-850/50">
                    <span className="text-zinc-500 uppercase text-[9px] font-bold">{i18n.t('knowledge_graph.sidebar_label_confidence')}</span>
