                    aria-label={`Edit Knowledge Card ${card.title}`}
                    title="Edit Card"
                    className="p-1.5 hover:bg-zinc-800 text-zinc-400 hover:text-emerald-400 rounded-lg transition-colors cursor-pointer"
                  >
                    <Edit2 className="w-3.5 h-3.5" />
