                            <tr>
                                <td colSpan={5} className="p-8 text-center text-zinc-600 italic">
                                    {i18n.t('security.status_recorded_none')}
                                </td>
                            </tr>
                        ) : audit_trail.map(entry => {
                            const agent_name = agent_health.find(h => h.agent_id === entry.agent_id)?.name || entry.agent_id;
                            // Parse execution outcome tag from the skill prefix
                            const outcomeTag = entry.skill?.match(/^\[(SUCCESS|FAILURE|INTENT)\]/)?.[1] ?? null;
                            const skillDisplay = entry.skill?.replace(/^\[(SUCCESS|FAILURE|INTENT)\]\s*/, '') ?? '—';
                            const skillColor = outcomeTag === 'FAILURE' ? 'text-red-400'
                                : outcomeTag === 'SUCCESS' ? 'text-emerald-400'
                                : outcomeTag === 'INTENT'  ? 'text-amber-400'
                                : 'text-green-400';
                            return (
                                <tr key={entry.id} className="hover:bg-zinc-800/20 transition-colors group">
                                    <td className="p-3 text-zinc-500 font-mono">
                                        {entry.decided_at ? (() => {
                                            const d = new Date(entry.decided_at);
                                            return isNaN(d.getTime()) ? i18n.t('security.status_pending') : d.toLocaleTimeString();
                                        })() : i18n.t('security.status_pending')}
                                    </td>
                                    <td className="p-3 text-zinc-300 font-medium">
                                        <div className="flex flex-col">
                                            <span>{agent_name}</span>
                                            <span className="text-[9px] text-zinc-600 font-mono uppercase">{entry.agent_id}</span>
                                        </div>
                                    </td>
                                    <td className="p-3 font-mono">
                                        {/* Colour-coded by execution outcome tag */}
                                        <span className={skillColor}>{skillDisplay || '—'}</span>
                                    </td>
                                    <td className="p-3">
                                        <Tooltip content={entry.id}>
                                            <span className="text-[9px] font-mono text-zinc-600 bg-zinc-900/50 px-1.5 py-0.5 rounded border border-zinc-800 cursor-help">
                                                {entry.id.substring(0, 8)}...
                                            </span>
                                        </Tooltip>
                                    </td>
                                    <td className="p-3">
                                        <div className="flex items-center gap-2">
                                            {/* Icon driven by execution outcome, not Merkle integrity */}
                                            {outcomeTag === 'FAILURE' ? (
                                                <XCircle size={12} className="text-red-500" />
                                            ) : outcomeTag === 'SUCCESS' ? (
                                                <CheckCircle2 size={12} className="text-emerald-500" />
                                            ) : (
                                                <Clock size={12} className="text-amber-400" />
                                            )}
                                            <span className={`uppercase font-bold tracking-tighter ${
                                                outcomeTag === 'FAILURE' ? 'text-red-400'
                                                : outcomeTag === 'SUCCESS' ? 'text-emerald-500'
                                                : 'text-amber-400'
                                            }`}>
                                                {outcomeTag ?? entry.decision ?? i18n.t('security.status_recorded')}
                                            </span>
                                            {/* Merkle integrity badge — separate from execution outcome */}
                                            {!entry.is_verified && (
                                                <Tooltip content="Merkle chain integrity check failed">
                                                    <AlertCircle size={10} className="text-red-500 ml-1 cursor-help" />
                                                </Tooltip>
                                            )}
                                        </div>
                                    </td>
                                </tr>
                            )
                        })}
                    </tbody>
                </table>
            </div>
            <div className="p-3 border-t border-[color:var(--color-border)] bg-zinc-950/10 flex items-center justify-between text-[10px] font-bold uppercase tracking-widest text-zinc-500">
                <div className="flex items-center gap-4">
                    <span>{i18n.t('common.label_page')} {audit_page} / {Math.max(1, Math.ceil(audit_total / 10))}</span>
                    <span>{i18n.t('common.label_total_records')}: {audit_total}</span>
                </div>
                <div className="flex items-center gap-2">
                    <button
                        disabled={audit_page <= 1}
                        onClick={() => set_audit_page(audit_page - 1)}
                        className="px-3 py-1 rounded bg-zinc-800 border border-zinc-700 hover:bg-zinc-700 disabled:opacity-30 transition-colors"
                    >
                        {i18n.t('common.label_previous')}
                    </button>
                    <button
                        disabled={audit_page >= Math.ceil(audit_total / 10)}
                        onClick={() => set_audit_page(audit_page + 1)}
                        className="px-3 py-1 rounded bg-zinc-800 border border-zinc-700 hover:bg-zinc-700 disabled:opacity-30 transition-colors"
                    >
                        {i18n.t('common.label_next')}
                    </button>
                </div>
            </div>
        </div>
    );
}

