import React from 'react';
import { Users, Check } from 'lucide-react';
import { i18n } from '../../i18n';
import type { Agent } from '../../types';

interface Assignment_Modal_Props {
    is_open: boolean;
    on_close: () => void;
    assign_target: { type: 'skill' | 'workflow' | 'mcp', name: string } | null;
    agents: Agent[];
    on_toggle_assignment: (agent_id: string) => void;
}

const getAssignmentStatus = (agent: Agent, target: { type: string, name: string }) => {
    const registry = {
        skill: agent.skills,
        workflow: agent.workflows,
        mcp: agent.mcp_tools
    };
    return (registry[target.type as keyof typeof registry] || []).includes(target.name);
};

export const Assignment_Modal: React.FC<Assignment_Modal_Props> = ({
    is_open,
    on_close,
    assign_target,
    agents,
    on_toggle_assignment
}) => {
    if (!is_open || !assign_target) return null;

    return (
        <div className="fixed inset-0 z-[60] bg-zinc-950/80 backdrop-blur-md flex items-center justify-center p-4">
            <div className="bg-[color:var(--color-background)] border border-[color:var(--color-border)] w-full max-w-md rounded-2xl shadow-2xl flex flex-col relative overflow-hidden">
                <div className="neural-grid opacity-10" />
                <div className="p-5 border-b border-[color:var(--color-border)] flex justify-between items-center shrink-0 relative z-10 bg-[color:color-mix(in_srgb,var(--color-background)_50%,transparent)]">
                    <h2 className="text-sm font-bold text-zinc-100 flex items-center gap-2 uppercase tracking-wider">
