                    </h2>
                    <button onClick={on_close} className="text-zinc-500 hover:text-zinc-300 p-1">✕</button>
                </div>
                <div className="p-6 space-y-4 relative z-10 bg-[color:color-mix(in_srgb,var(--color-background)_80%,transparent)]">
