                        {i18n.t('agent_manager.label_select_agents')}
                    </p>
                    <div className="space-y-2 max-h-64 overflow-y-auto custom-scrollbar pr-2">
                        {agents.map(agent => {
                            const is_assigned = getAssignmentStatus(agent, assign_target);

                            return (
                                <button
                                    key={agent.id}
