export const get_route_by_path = (path: string) => {
  const clean_path = (path || '').split('?')[0].split('#')[0].trim();
  const normalized = !clean_path || clean_path === '/' ? '/dashboard' : clean_path.replace(/\/$/, '');
  return APP_ROUTES.find(r => r.path === normalized) || APP_ROUTES[0];
};

