import { useEffect, useCallback } from 'react';
import { use_workspace_store } from '../stores/workspace_store';
import { use_agent_store } from '../stores/agent_store';

export function useWorkspacesManager() {
    const { 
        clusters, 
        approve_branch, 
        reject_branch, 
        sync_status, 
        refresh_sync_status 
    } = use_workspace_store();

    const agents = use_agent_store(state => state.agents);
    const fetch_agents = use_agent_store(state => state.fetch_agents);

    useEffect(() => {
        void fetch_agents();
        refresh_sync_status();

        const interval = setInterval(refresh_sync_status, 15000);
        return () => clearInterval(interval);
    }, [refresh_sync_status, fetch_agents]);

    const format_bytes = useCallback((bytes: number) => {
        if (!Number.isFinite(bytes) || bytes <= 0) return '0 B';
        const k = 1024;
        const sizes = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'];
        const i = Math.min(Math.floor(Math.log(bytes) / Math.log(k)), sizes.length - 1);
        return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
    }, []);

    return {
        clusters,
        agents,
        sync_status,
        approve_branch,
        reject_branch,
        refresh_sync_status,
        format_bytes
    };
}

