        agents,
        user_agents_count,
        ai_agents_count,
        selected_agent,
        is_creating,
        search_query,
        filter_role,
        active_tab,
        filter_roles,

        set_selected_agent,
        set_is_creating,
        set_search_query,
        set_filter_role,
