            else if (url.includes('/engine/templates/installed')) res_body = { status: 'ok', swarms: [] };
            else if (url.includes('/engine/templates/uninstall')) res_body = { status: 'ok', uninstalled: true };
            else if (url.includes('/engine/templates/install') || url.includes('/engine/templates/import')) res_body = { status: 'success' };
            else if (url.includes('/system/environment')) res_body = { status: 'success', updated_keys: [] };
            else return { ok: false, status: 404 };

            return {
                ok: true,
                status: 200,
                text: async () => JSON.stringify(res_body),
