        use_trace_store.getState().clear_all();
    });

    const mock_span_1: Trace_Span = {
        id: 'span1',
        trace_id: 'trace-123',
        name: 'test_span',
        agent_id: 'agent1',
        mission_id: 'mission1',
        start_time: 1000,
        last_activity_at: 1000,
        status: 'success',
