        it('fallbacks to slot 1 for unknown or undefined inputs', () => {
            expect(parse_active_model_slot(undefined)).toBe(1);
            expect(parse_active_model_slot(null)).toBe(1);
            expect(parse_active_model_slot('unknown')).toBe(1);
