import { describe, it, expect, vi } from 'vitest';
import { SkillParser } from './skill_parser';

describe('SkillParser', () => {
    it('parses a skill from a JSON markdown block', () => {
        const content = `
# My Skill
This is a skill.
\`\`\`json
{
    "name": "test-skill",
